    static let schemaJSON = #"""
{"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://ypr.app/schemas/app-actions/v1","title":"Yapper shared app actions","x-protocolVersion":1,"x-actions":[{"id":"app.dictionary.addTerm","symbol":"dictionaryAdd","input":"DictionaryAddInput","description":"Add a spelling to the dictionary, with optional aliases it is often misheard as. Adding a term that exists replaces its aliases.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"app.dictionary.editTerm","symbol":"dictionaryEdit","input":"DictionaryEditInput","description":"Change a term listed in dictionary: respell it, add aliases, or remove aliases. Send only what changes.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"app.dictionary.removeTerm","symbol":"dictionaryRemove","input":"DictionaryRemoveInput","description":"Remove a term listed in dictionary, with its aliases.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"app.projects.create","symbol":"projectCreate","input":"ProjectCreateInput","description":"Create a new empty project with this name and open it. The open project is saved first. Ends the current editing conversation, so run it alone.","effect":"navigation","requiresRebuild":false,"runtime":"client"},{"id":"app.projects.duplicate","symbol":"projectDuplicate","input":"ProjectDuplicateInput","description":"Copy a project from projectLibrary, the open one included, and open the copy.","effect":"navigation","requiresRebuild":false,"runtime":"client"},{"id":"app.projects.open","symbol":"projectOpen","input":"ProjectOpenInput","description":"Open a project from projectLibrary by its id. The open project is saved first.","effect":"navigation","requiresRebuild":false,"runtime":"client"},{"id":"app.projects.rename","symbol":"projectRename","input":"ProjectRenameInput","description":"Rename the open project and its folder in the library.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"app.projects.trash","symbol":"projectTrash","input":"ProjectTrashInput","description":"Move a project from projectLibrary to the Finder Trash, where the creator can restore it. The creator is asked to confirm first.","effect":"destructive","confirm":true,"requiresRebuild":false,"runtime":"client"},{"id":"editor.audio.addAt","symbol":"soundAt","input":"SoundAtInput","description":"Place an installed library sound at one or more timing anchors: explicit timeline times, playhead, speechStart, exact phrase/occurrence, or a saved animation event ID. Uses the same timing resolver as keyframes. Repeating the same effect at the same time is a no-op. Changes audio only.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.audio.addSaved","symbol":"savedAudioAdd","input":"SavedAudioAddInput","description":"Place existing audio from savedAudioLibrary at a timeline anchor. Keeps the library default volume and adds the actual saved source; no paths are accepted.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.audio.replace","symbol":"audioReplace","input":"AudioReplaceInput","description":"Replace existing sound layers with a built-in sound from soundLibrary, keeping timeline placement and volume. Resets source trim and rate to the new sound.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.audio.setVolume","symbol":"audioVolume","input":"AudioVolumeInput","description":"Set playback volume (0 silent, 1 unity, up to 2) on explicit audio layer IDs and, when videoTrack is true, on the speaker's own video track. Raising the video track above 0 also unmutes it.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.audio.trim","symbol":"audioTrim","input":"AudioTrimInput","description":"Set source in point and/or duration of existing audio layers. Preserve timeline position, volume and speed. SourceStart is recording seconds; duration is timeline seconds.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.background.set","symbol":"clipBackground","input":"ClipBackgroundInput","description":"Keep or remove the room behind the speaker on explicit clip IDs. When removed, the project backdrop colour shows behind the speaker. Locked clips are skipped.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.captions.add","symbol":"captionAdd","input":"CaptionAddInput","description":"Add a caption card. Either at a timeline anchor over spoken footage, or right after an existing caption (afterCaptionID). Optional text sets what the card says; otherwise it takes the spoken words there.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.captions.merge","symbol":"captionMerge","input":"CaptionMergeInput","description":"Merge two or more caption cards into one card spanning them, keeping their words in order.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.captions.remove","symbol":"captionRemove","input":"CaptionRemoveInput","description":"Remove explicit caption cards by ID. Locked captions are skipped. To hide all captions without deleting them use editor.captions.setVisible.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.captions.retime","symbol":"captionRetime","input":"CaptionRetimeInput","description":"Move a caption card to a new timeline start and end in seconds. A card can only sit over the footage it was spoken over.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.captions.setStyle","symbol":"captionStyle","input":"CaptionStyleInput","description":"Set caption style fields on explicit caption IDs, or on the shared caption style when applyToAll is true. Send only the fields to change; unmentioned fields keep their values. Locked captions are skipped. Position, width and fontScale are fractions of the frame; strokeWidth is a fraction of the font size.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.captions.setText","symbol":"captionText","input":"CaptionTextInput","description":"Replace the text of one caption card. The card stops following the transcript for that text.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.captions.setVisible","symbol":"captionVisibility","input":"CaptionVisibilityInput","description":"Show or hide existing captions, preserving their text and styling. If showing captions for the first time, generate them from speech using the caption workflow.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.captions.splitAtWord","symbol":"captionSplit","input":"CaptionSplitInput","description":"Split one caption after a word count, as pressing Enter at a word boundary. Locked captions are skipped.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.cleanup","symbol":"cleanupWorkflow","input":"CleanupWorkflowInput","description":"Run the app one-click AI cleanup workflow on the project.","effect":"workflow","requiresRebuild":true,"runtime":"client"},{"id":"editor.clips.extractAudio","symbol":"extractAudio","input":"ExtractAudioInput","description":"Extract audio from explicit video clip or overlay IDs into independent audio layers, preserving trim and speed and silencing the original clips. Locked, silent and already extracted clips are skipped.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.clips.reorder","symbol":"clipReorder","input":"ClipReorderInput","description":"Move explicit main-track clips as one block so it starts at insertionIndex among the remaining clips (0 is first). Cannot reorder across a locked clip.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.clips.setSpeed","symbol":"clipSpeed","input":"ClipSpeedInput","description":"Set playback speed for explicit clip IDs, preserving voice pitch. Locked clips are skipped.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.designOverlays","symbol":"overlayWorkflow","input":"OverlayWorkflowInput","description":"Overlays from the creator's own files or newly created visuals. mode placeImported puts media files the creator imported (media with onMainTrack and usedAsOverlay both false) on the timeline at the moments they fit the speech, with any sounds asked for on them, for example a cha-ching exactly when a number is said. mode create designs new visuals (charts, counters, animated graphics) that do not exist yet. Pass the creator's whole request as the instruction; the workflow reads the transcript and media itself. Never use this to edit existing masks.","effect":"workflow","requiresRebuild":true,"runtime":"client"},{"id":"editor.export","symbol":"exportVideo","input":"ExportInput","description":"Export the current edited video. destination=file opens the normal save panel. Use poster only when explicitly asked to send the final video to Poster: it uploads the export and opens Poster without publishing. Runs alone.","effect":"workflow","requiresRebuild":true,"runtime":"client"},{"id":"editor.history.restore","symbol":"history","input":"HistoryInput","description":"Undo or redo the last saved edit, including a whole Chirpy batch. Runs alone and uses the existing history stack. Check canUndo/canRedo.","effect":"workflow","requiresRebuild":true,"runtime":"client"},{"id":"editor.masks.remove","symbol":"maskRemove","input":"MaskRemoveInput","description":"Remove one explicitly requested mask region and its opacity animation, leaving all other masks and original pixels intact.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.masks.setRegion","symbol":"maskRegion","input":"MaskRegionInput","description":"Create or edit a rectangular solid-color mask on an image or generated overlay. Coordinates are source-image fractions from its top left; RGB values are 0\u20131. Use the attached source image to locate any requested area (text, face, logo, chart, or other content); OCR is optional evidence, not a requirement. Omit regionID to create a mask; use a saved ID to edit one. opacityKeys animate the cover: 1 conceals the area, 0 exposes it. The first opacity is held before the first key and the last after the last key: include the initial covered state explicitly before a fade. Each key accepts a shared timing anchor, including exact speech phrases. New masks default to a solid cover. Geometry-only edits omit opacityKeys and policy to preserve existing timing. policy/revealTime are compatibility shortcuts; use opacityKeys for new animations. Image conversion supports scene source durations of 0.5\u201330 seconds. Preserve unmentioned masks and source pixels. Unsupported mask styles, shapes, or moving-object tracking must be reported as unavailable.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.media.edit","symbol":"mediaEdit","input":"MediaEditInput","description":"Append imported media to the main track, remove media and its timeline instances (original files kept), or reset its main-track cuts to the full source. Uses media IDs from context. Removing/resetting locked clips is rejected.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.media.import","symbol":"importPicker","input":"ImportPickerInput","description":"Open the same local file picker as Import media or Import audio, then import the creator-selected files. You cannot choose filesystem paths. Runs alone. The creator may cancel.","effect":"workflow","requiresRebuild":true,"runtime":"client"},{"id":"editor.overlays.add","symbol":"overlayAdd","description":"Place one existing media item as an overlay at a known timeline anchor. Optional duration and sourceStart; defaults match Add as overlay. Use designOverlays/placeImported only when editorial placement across speech must be decided.","input":"OverlayAddInput","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.overlays.editTrack","symbol":"overlayTrack","description":"Remove an overlay lane and compact remaining lanes, or set every overlay on it hidden/shown. track is zero-based. Removing keeps original media.","input":"OverlayTrackInput","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.overlays.keyframe","symbol":"overlayKeyframe","input":"OverlayKeyframeInput","description":"Set, remove, move or clear a keyframe on an overlay. time and destination are seconds from the overlay start. A set with no box or crop captures the current frame. box uses fractions of the video frame; crop uses normalized source coordinates. clear freezes the frame at time.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.overlays.setCrop","symbol":"overlayCrop","input":"OverlayCropInput","description":"Crop explicit overlays to a source rectangle. Coordinates are normalized with top-left origin. Optional time sets the crop at that local overlay time when a single image or scene already has keyframes. Omitting time explicitly replaces crop animation with a static crop while preserving placement keyframes.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.overlays.setFrame","symbol":"overlayFrame","description":"Set size, position and rotation of existing overlays. Use all=true and overlayIDs=[] for every overlay in one action. fit=full is the manual Full frame control (x/y=0, width/height=1); fit=card resets the frame using each source aspect. Otherwise supply only changed fields. Width without height preserves source aspect and center. Omit time to apply throughout each overlay, including every placement key, preserving crop keys/easing. time edits one overlay at an overlay-local keyframe. Does not place or generate media.","input":"OverlayFrameInput","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.overlays.setProperties","symbol":"overlayProperties","description":"Edit existing overlays: visibility, behind-speaker depth, source in point, timeline start/duration, or zero-based lane. Only supplied fields change. all=true targets every overlay; otherwise use overlayIDs. Cannot put generated scenes behind the speaker, exceed video source bounds, or collide on a lane.","input":"OverlayPropertiesInput","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.overlays.zoom","symbol":"overlayZoom","input":"OverlayZoomInput","description":"Animate a zoom into a specific source region of an existing overlay, preserving its placement and masks. target is normalized source coordinates with a top-left origin. Times are seconds from the overlay start. Smooth zoom holds after endTime; optional returnStart and returnEnd zoom back. Use known region boxes or the supplied selected-overlay image to locate the requested section; ask if the target region is ambiguous.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.project.setBackdrop","symbol":"projectBackdrop","input":"ProjectBackdropInput","description":"Set the project backdrop colour that fills the frame where there is no picture, including behind a speaker whose background is removed.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.project.setSettings","symbol":"projectSettings","description":"Set project aspect ratio, visual filter/strength, video-track visibility or mute. Only supplied fields change. Applies the same project-wide settings as the manual controls.","input":"ProjectSettingsInput","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.retouch.set","symbol":"clipRetouch","input":"ClipRetouchInput","description":"Set face retouch strengths (0 to 1) on explicit clip IDs: clearBlemishes and whitenTeeth. Send only the fields to change. Locked clips are skipped.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.reveals.setPolicy","symbol":"revealPolicy","input":"RevealPolicyInput","description":"Set visibility policies for explicit regions of an image overlay. alwaysVisible removes only those masks; untilCue uses the saved spoken cue; alwaysHidden requires an explicit request to keep a value hidden.","effect":"reversibleEdit","requiresRebuild":true,"legacy":true,"runtime":"client"},{"id":"editor.sounds.addAtReveals","symbol":"revealSounds","input":"RevealSoundsInput","description":"Add a library sound at explicit saved reveal events, using the animation times already in the scene. Does not add or move overlays. Repeating the same sound at the same reveal is a no-op.","effect":"reversibleEdit","requiresRebuild":true,"legacy":true,"runtime":"client"},{"id":"editor.text.add","symbol":"textLayerAdd","input":"TextLayerAddInput","description":"Add an on-screen text layer with the given text at a timeline anchor (default the playhead) for duration seconds (default 5). asHook places it at the very start with the hook look.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.text.setStyle","symbol":"textLayerStyle","input":"TextLayerStyleInput","description":"Set style fields on explicit text layer IDs. Same fields and units as caption style; send only the fields to change.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.text.update","symbol":"textLayerUpdate","input":"TextLayerUpdateInput","description":"Change a text layer's words, timeline start, or duration. Send only the fields to change. Remove a layer with editor.timeline.delete.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.timeline.clearTrack","symbol":"clearTrack","input":"ClearTrackInput","description":"Clear all main-track clips, or all captions and caption visibility, as the manual clear-track control. Original media stays in the bin. Locked content is protected.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.timeline.delete","symbol":"timelineDelete","input":"TimelineDeleteInput","description":"Remove explicit timeline items by ID: clips, captions, text layers, overlays, or sounds. Removing a clip closes the gap. Locked clips and captions are skipped.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.timeline.setLocked","symbol":"timelineLock","input":"TimelineLockInput","description":"Lock or unlock explicit clips and captions to protect their edits.","effect":"reversibleEdit","requiresRebuild":false,"runtime":"client"},{"id":"editor.timeline.shift","symbol":"timelineShift","input":"TimelineShiftInput","description":"Slide explicit captions, text layers, overlays, or sounds along the timeline by deltaSeconds (negative is earlier), clamped to the project. Clips are in a running order; use editor.clips.reorder for them.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.timeline.split","symbol":"timelineSplit","input":"TimelineSplitInput","description":"Split explicit timeline items (clips, captions, text layers, overlays, sounds) at one timeline anchor. Items the anchor does not fall inside are left alone. Locked clips and captions are skipped. The receipt names each new tail ID.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.timeline.transfer","symbol":"trackTransfer","input":"TrackTransferInput","description":"Move a clip to an overlay lane or an overlay onto the main track. toOverlay requires itemID of an unlocked clip and optional at/track; at is a timeline anchor. toMainTrack requires overlay itemID and insertionIndex (0-based). Keeps source trim and speed. At least one main-track clip must remain.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.timeline.trim","symbol":"timelineTrim","input":"TimelineTrimInput","description":"Move the leading or trailing edge of explicit timeline items to one timeline anchor. leading keeps everything after the anchor; trailing keeps everything before it. The anchor must fall inside each item. Locked items are skipped.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.transcribe","symbol":"transcribeWorkflow","input":"TranscribeWorkflowInput","description":"Transcribe the project speech using the app transcription workflow.","effect":"workflow","requiresRebuild":true,"runtime":"client"},{"id":"editor.transcript.setPauseKept","symbol":"transcriptPause","input":"TranscriptPauseInput","description":"Cut a pause (a stretch of a recording with no words, given in recording seconds for that media) out of the edit, or restore it.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.transcript.setWordRangesKept","symbol":"transcriptWordRanges","input":"TranscriptWordRangesInput","description":"Cut spoken words out of the edit (kept false) or put cut words back (kept true) by the word numbers in context.transcript. Each range covers first through last inclusive; one word is a range with first equal to last. Cutting removes that stretch of recording from the timeline; restoring brings it and its caption back.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.transcript.setWordsKept","symbol":"transcriptWords","input":"TranscriptWordsInput","description":"Cut spoken words out of the edit (kept false) or put cut words back (kept true) by transcript word ID. Cutting removes that stretch of recording from the timeline; restoring brings it and its caption back.","effect":"reversibleEdit","requiresRebuild":true,"legacy":true,"runtime":"client"},{"id":"editor.trimSilences","symbol":"silenceWorkflow","input":"SilenceWorkflowInput","description":"Trim silences using the app silence trimming workflow. With clipIDs, only silences inside those main-track clips are cut; without, the whole timeline is trimmed.","effect":"workflow","requiresRebuild":true,"runtime":"client"},{"id":"editor.video.animateFraming","symbol":"framingAnimation","input":"FramingAnimationInput","description":"Animate main-video scale, position, and rotation with ordered keyframes. Each key has a timeline timing anchor and a scale multiplier relative to the existing framing; optional x/y are frame-fraction offsets and rotation is a degree offset. easing controls the segment leading to the next key. pivot face keeps the detected face in place while scaling; frameCenter uses the current framing center. Existing keys outside the key interval and all other tracks are preserved. Keys may span video cuts. Use real times or local phrase/speechStart anchors; ambiguous or missing cues are rejected. Include a final multiplier 1 with zero offsets when returning to the existing framing. There is no implicit entry key: to begin smoothly from the existing framing, explicitly include an initial scaleMultiplier 1 with zero offsets at the beginning of the move, followed by the changed framing at its arrival time.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.video.framingKey","symbol":"videoFramingKey","input":"VideoFramingKeyInput","description":"Set, remove, move or clear absolute video framing keys on a clip, like the manual diamonds. sourceTime/destination are recording seconds inside that clip, not timeline time. set without framing fields captures the current framing. clear leaves framing sampled at sourceTime. Locked clips are skipped.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"},{"id":"editor.video.setFraming","symbol":"videoFraming","input":"VideoFramingInput","description":"Set the static framing of explicit main-video clip IDs: scale multiplier, x/y offset as frame fractions, rotation in degrees. Send only the fields to change. Clips with framing keyframes are rejected; use editor.video.animateFraming for those. Locked clips are skipped.","effect":"reversibleEdit","requiresRebuild":true,"runtime":"client"}],"$defs":{"AppActionRuntime":{"type":"string","description":"Where an action executes. Client actions run in the app's registry; server actions run inside the Chirpy turn loop.","enum":["client","server"]},"AppActionEffect":{"type":"string","description":"What running an action does. destructive, external and standingRule actions must set confirm: true.","enum":["read","reversibleEdit","serverEdit","paidGeneration","destructive","external","standingRule","navigation","workflow"]},"ActionRect":{"type":"object","additionalProperties":false,"required":["x","y","width","height"],"properties":{"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1},"width":{"type":"number","minimum":0.005,"maximum":1},"height":{"type":"number","minimum":0.005,"maximum":1}}},"OverlayKeyOperation":{"type":"string","enum":["set","remove","clear","move"]},"TimelineAnchorKind":{"type":"string","enum":["time","playhead","speechStart","phrase","event"]},"TimelineAnchorInput":{"type":"object","properties":{"kind":{"$ref":"#/$defs/TimelineAnchorKind","description":"speechStart is the beginning of speech, including entering/starting speaking; it requires no phrase. Use phrase for a specifically quoted part of speech, time for an explicit timestamp, playhead for here/now, event for an existing animation moment."},"time":{"type":"number","minimum":0,"maximum":86400},"phrase":{"type":"string","minLength":1,"maxLength":300},"occurrence":{"type":"integer","minimum":1,"maximum":1000},"eventID":{"type":"string","minLength":1,"maxLength":200},"offset":{"type":"number","minimum":-86400,"maximum":86400}},"required":["kind"],"additionalProperties":false,"description":"A reusable timeline cue resolved locally from the current edit. speechStart means the first kept spoken word: no phrase or timestamp is required. phrase finds exact words, accounting for trims, cuts and playback speed; occurrence selects a repeated match. playhead means the current position. time uses explicit timeline seconds. event uses a saved animationEvents ID. offset adds seconds after resolution (negative is before)."},"AnimationEase":{"type":"string","enum":["linear","smooth"]},"AppActionStatus":{"type":"string","enum":["applied","unchanged","rejected","failed","canceled"]},"AppActionRequest":{"type":"object","additionalProperties":false,"required":["protocolVersion","id","projectID","revision","action","arguments"],"properties":{"protocolVersion":{"type":"integer","const":1},"id":{"type":"string","format":"uuid"},"projectID":{"type":"string","format":"uuid"},"revision":{"type":"integer","minimum":0},"action":{"type":"string","minLength":1,"maxLength":120},"arguments":{"type":"object","additionalProperties":{}}}},"AppActionChange":{"type":"object","additionalProperties":false,"required":["targetID","property","before","after"],"properties":{"targetID":{"type":"string","format":"uuid"},"property":{"type":"string"},"before":{"type":"string"},"after":{"type":"string"}}},"AppActionResult":{"type":"object","additionalProperties":false,"required":["protocolVersion","invocationID","projectID","revision","action","status","message","changes","skippedIDs","persisted"],"properties":{"protocolVersion":{"type":"integer","const":1},"invocationID":{"type":"string","format":"uuid"},"projectID":{"type":"string","format":"uuid"},"revision":{"type":"integer","minimum":0},"action":{"type":"string"},"status":{"$ref":"#/$defs/AppActionStatus"},"message":{"type":"string"},"changes":{"type":"array","items":{"$ref":"#/$defs/AppActionChange"}},"skippedIDs":{"type":"array","items":{"type":"string","format":"uuid"}},"persisted":{"type":"boolean"}}},"ChirpyActionCall":{"type":"object","additionalProperties":false,"required":["action","arguments"],"properties":{"action":{"type":"string","minLength":1,"maxLength":120},"arguments":{"type":"object","additionalProperties":{}}}},"ChirpyPlanReply":{"type":"object","additionalProperties":false,"required":["message","actions"],"properties":{"message":{"type":"string","maxLength":2000},"actions":{"type":"array","items":{"$ref":"#/$defs/ChirpyActionCall"},"maxItems":8}}},"DictionaryAddInput":{"type":"object","additionalProperties":false,"required":["term"],"properties":{"term":{"type":"string","minLength":1,"maxLength":80},"aliases":{"type":"array","maxItems":20,"items":{"type":"string","minLength":1,"maxLength":80}}}},"DictionaryEditInput":{"type":"object","additionalProperties":false,"required":["term"],"properties":{"term":{"type":"string","minLength":1,"maxLength":80},"newTerm":{"type":"string","minLength":1,"maxLength":80},"addAliases":{"type":"array","maxItems":20,"items":{"type":"string","minLength":1,"maxLength":80}},"removeAliases":{"type":"array","maxItems":20,"items":{"type":"string","minLength":1,"maxLength":80}}}},"DictionaryRemoveInput":{"type":"object","additionalProperties":false,"required":["term"],"properties":{"term":{"type":"string","minLength":1,"maxLength":80}}},"ProjectCreateInput":{"type":"object","additionalProperties":false,"required":["name"],"properties":{"name":{"type":"string","minLength":1,"maxLength":120}}},"ProjectOpenInput":{"type":"object","additionalProperties":false,"required":["projectID"],"properties":{"projectID":{"type":"string","format":"uuid"}}},"ProjectRenameInput":{"type":"object","additionalProperties":false,"required":["name"],"properties":{"name":{"type":"string","minLength":1,"maxLength":120}}},"ProjectDuplicateInput":{"type":"object","additionalProperties":false,"required":["projectID"],"properties":{"projectID":{"type":"string","format":"uuid"}}},"ProjectTrashInput":{"type":"object","additionalProperties":false,"required":["projectID"],"properties":{"projectID":{"type":"string","format":"uuid"}}},"ExtractAudioInput":{"type":"object","additionalProperties":false,"required